struct frame { uint8_t tag; uint32_t len; };   /* fixed, byte-ordered header */

int dispatch(const uint8_t *buf, size_t n) {
    uint8_t tag;
    uint32_t len;
    const uint8_t *body;

    if (parse_header(buf, n, &tag, &len, &body) != 0)
        return dead_letter(buf, n);              /* malformed: fail closed */
    switch (tag) {                               /* the tag picks the decoder */
    case MSG_ORDER:  return order_decode(body, len);
    case MSG_CANCEL: return cancel_decode(body, len);
    default:         return dead_letter(buf, n); /* unknown tag: fail closed */
    }
}
